// Preserve the actual platform failure, including a stable POSIX name where
// the standard error condition provides one. No path existence guess replaces it.
std::string TraceFileError(const std::error_code& code){
  const char* name=nullptr;
  for(const auto& [condition,label]:std::initializer_list<std::pair<std::errc,const char*>>{{std::errc::no_such_file_or_directory,"ENOENT"},{std::errc::not_a_directory,"ENOTDIR"},{std::errc::file_exists,"EEXIST"},{std::errc::permission_denied,"EACCES"},{std::errc::operation_not_permitted,"EPERM"},{std::errc::read_only_file_system,"EROFS"},{std::errc::no_space_on_device,"ENOSPC"},{std::errc::is_a_directory,"EISDIR"},{std::errc::too_many_files_open,"EMFILE"},{std::errc::filename_too_long,"ENAMETOOLONG"}})if(code==std::make_error_condition(condition)){name=label;break;}
  return (name?std::string(name):std::string(code.category().name()))+" ("+code.message()+", code "+std::to_string(code.value())+")";
}
