void TraceControls::Closed(int context){if(live_)live_->Abort(context);const auto ending=journal_.SessionLease(context);journal_.Closed(context);chunk_names_.erase(context);if(ending.context&&hooks_.end_session)hooks_.end_session(ending);errors_.erase(context);for(auto it=calls_.begin();it!=calls_.end();)if(it->second.context==context)it=calls_.erase(it);else++it;std::vector<int> owners;for(const auto& [owner,work]:terminal_)if(work.context==context)owners.push_back(owner);for(const auto& [owner,pending]:pending_)if(pending->context==context)owners.push_back(owner);for(int owner:owners)Cancel(owner);}
void TraceControls::Clear(){if(live_)live_->Clear();if(hooks_.end_session)for(const auto& lease:journal_.Sessions())hooks_.end_session(lease);journal_.Clear();std::vector<int> owners;for(const auto& [owner,work]:terminal_)owners.push_back(owner);for(const auto& [owner,pending]:pending_)owners.push_back(owner);for(int owner:owners)Cancel(owner);calls_.clear();errors_.clear();chunk_names_.clear();}
bool TraceControls::ContextReady(int context) const {if(stopping_.contains(context)||(live_&&live_->Busy(context)))return false;for(const auto& [owner,pending]:pending_)if(pending->context==context)return false;return true;}
void TraceControls::Diagnostics(Dict output) const{output->SetInt("nativeTraceContexts",int(journal_.Contexts()));output->SetDouble("nativeTraceBytes",double(journal_.Bytes()));output->SetInt("nativeTracePhysical",int(PhysicalCount()));output->SetDouble("nativeTraceLiveSnapshotBytes",live_?double(live_->Bytes()):0);output->SetInt("nativeTraceWaitingStop",int(terminal_.size()));output->SetInt("nativeTracePendingActions",int(calls_.size()));}
